  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;''','''export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  // mqpub 3.x는 한 배치 안에서 키의 "앞 16바이트"가 같으면 첫 메시지만 남기고 조용히 버린다.
